class TablePDF:
    """x*f_q and x*f_qbar for q = d,u,s,c,b from the embedded grid.

    Conventions follow PYTHIA's LHAPDF wrapper as used in qqbar_bbbar_xsec.py:
    values are frozen at the table edges, negative values are clipped to zero,
    and cbar/bbar are taken equal to c/b.
    """
    def __init__(self, tables):
        self.lx = np.log(tables["x_knots"])
        self.lq = np.log(tables["q2_knots"])
        self.flavours = tables["flavours"]
        self.splines = {f: RectBivariateSpline(self.lx, self.lq, np.asarray(g), kx=3, ky=3)
                        for f, g in zip(self.flavours, tables["xf"])}
        self.frozen = 0

    def xf(self, x, q2):
        """Return arrays (5, N) of x*f_q and x*f_qbar."""
        lx = np.log(x)
        lq = np.log(q2)
        self.frozen += int(np.count_nonzero((lx < self.lx[0]) | (lq < self.lq[0]) | (lq > self.lq[-1])))
        lx = np.clip(lx, self.lx[0], self.lx[-1])
        lq = np.clip(lq, self.lq[0], self.lq[-1])
        q = np.array([self.splines[f].ev(lx, lq) for f in (1, 2, 3, 4, 5)])
        qbar = np.array([self.splines[f].ev(lx, lq) for f in (-1, -2, -3)] + [q[3], q[4]])
        return np.clip(q, 0, None), np.clip(qbar, 0, None)


class TableAlphaS:
    def __init__(self, tables):
        self.q2 = np.asarray(tables["alpha_q2"])
        self.interp = PchipInterpolator(np.log(self.q2), tables["alpha_s"], extrapolate=False)

    def __call__(self, q2):
        q2 = np.asarray(q2, dtype=float)
        if np.any(q2 < self.q2[0]) or np.any(q2 > self.q2[-1]):
            raise ValueError("Q^2 outside the embedded alpha_s table; re-run dump_standalone_tables.py "
                             "with a wider range")
        return self.interp(np.log(q2))


def dsigma_dcostheta(shat, costheta, mb, alpha_s):
    """Spin/colour averaged LO d(sigma_hat)/dcos(theta) in pb (PDG Eq. 51.20)."""
    rho = 4.0 * mb * mb / shat
    return np.where(rho < 1.0,
                    math.pi * alpha_s**2 * np.sqrt(np.clip(1.0 - rho, 0, None)) / (9.0 * shat)
                    * (1.0 + costheta**2 + rho * (1.0 - costheta**2)) * GEV2_TO_PB, 0.0)


def born_weights(points, ecm, mb, ptmin, ptmax, pdf, alpha):
    """Map unit-cube points (N,3) -> per-flavour weights (5,N), see qqbar_bbbar_xsec.py.

    Variables: log(tau), pair rapidity Y, |cos(theta)| within the pT window.
    Both beam orientations and both signs of cos(theta) are included.
    """
    s, mb2 = ecm**2, mb**2
    lo = 4.0 * (mb2 + ptmin**2)
    if lo >= s:
        return np.zeros((5, len(points)))
    loglo, logwidth = math.log(lo / s), math.log(s / lo)
    logtau = loglo + logwidth * points[:, 0]
    tau = np.exp(logtau)
    shat = tau * s
    ymax_kin = -0.5 * logtau
    boost = (2.0 * points[:, 1] - 1.0) * ymax_kin
    x1 = np.exp(0.5 * logtau + boost)
    x2 = np.exp(0.5 * logtau - boost)
    p2 = np.clip(shat / 4.0 - mb2, 0.0, None)
    ok = (p2 > ptmin**2) & (ymax_kin > 0)
    p2s = np.where(ok, p2, ptmin**2 + 1.0)          # safe values where not ok
    cmax = np.sqrt(np.clip(1.0 - ptmin**2 / p2s, 0.0, None))
    if ptmax is None:
        cmin = np.zeros_like(cmax)
        span = cmax
    else:
        cmin = np.where(ptmax**2 < p2s, np.sqrt(np.clip(1.0 - ptmax**2 / p2s, 0.0, None)), 0.0)
        span = np.where(cmin > 0, (ptmax**2 - ptmin**2) / (p2s * (cmax + cmin)), cmax - cmin)
    c = cmin + span * points[:, 2]
    pt2 = p2s * (1.0 - c) * (1.0 + c)
    q2 = pt2 + mb2                                   # muR^2 = muF^2 = mT^2 (PYTHIA codes 1-3)
    a = alpha(q2)
    aq, abar = pdf.xf(x1, q2)
    bq, bbar = pdf.xf(x2, q2)
    w = logwidth * 2 * ymax_kin * 2 * span * dsigma_dcostheta(shat, c, mb, a)
    w = np.where(ok, w, 0.0)
    return w * (aq * bbar + abar * bq)


def integrate(ecm, mb, ptmin, ptmax, power, repeats, seed, pdf, alpha, progress=True):
    totals = []
    for r in range(repeats):
        pts = qmc.Sobol(d=3, scramble=True, seed=seed + r).random_base2(power)
        totals.append(born_weights(pts, ecm, mb, ptmin, ptmax, pdf, alpha).mean(axis=1))
        if progress and repeats > 1:
            print(f"  repeat {r+1}/{repeats}: {totals[-1].sum()/1000:.6f} nb", flush=True)
    totals = np.asarray(totals)                    # (repeats, 5)
    mean = totals.mean(axis=0)
    err = totals.std(axis=0, ddof=1) / math.sqrt(repeats) if repeats > 1 else np.full(5, np.nan)
    tot = totals.sum(axis=1)
    return mean, err, float(tot.mean()), (float(tot.std(ddof=1) / math.sqrt(repeats)) if repeats > 1 else float("nan"))


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--ecm", type=float, default=13600.0)
    p.add_argument("--mb", type=float, default=4.8)
    p.add_argument("--ptmin", type=float, default=30.0)
    p.add_argument("--ptmax", type=float, default=None)
    p.add_argument("--power", type=int, default=16, help="2**power Sobol points per repeat")
    p.add_argument("--repeats", type=int, default=1, help=">1 gives an integration error estimate")
    p.add_argument("--seed", type=int, default=24680)
    p.add_argument("--reference-nb", type=float, default=18.44)
    args = p.parse_args()
    if TABLES is None:
        sys.exit("Tables missing: run dump_standalone_tables.py in the full environment first.")
    if args.ptmin <= 0 or (args.ptmax is not None and args.ptmax <= args.ptmin) or args.repeats < 1:
        sys.exit("Require ptmin>0, ptmax>ptmin, repeats>=1")
    pdf, alpha = TablePDF(TABLES), TableAlphaS(TABLES)
    q2min = args.ptmin**2 + args.mb**2
    if q2min < TABLES["q2_knots"][0] or args.ecm**2 / 4 > TABLES["q2_knots"][-1]:
        sys.exit(f"Embedded PDF table covers Q^2 in [{TABLES['q2_knots'][0]:.0f}, {TABLES['q2_knots'][-1]:.3g}] "
                 "GeV^2 only; re-run dump_standalone_tables.py for other kinematics")
    print(f"Standalone tables: {TABLES['pdf_set']}/{TABLES['member']} (LHAPDF {TABLES['lhapdf_version']}), "
          f"PYTHIA alpha_s order {TABLES['pythia_alpha_s']['order']}, alphaS(MZ)={TABLES['pythia_alpha_s']['alphas_mz']}")
    print(f"eCM={args.ecm:g}; mb={args.mb:g}; pTHat >= {args.ptmin:g} GeV; pTHat upper limit={args.ptmax}")
    print(f"Sobol 2^{args.power} points x {args.repeats} repeat(s)", flush=True)
    mean, err, total, error = integrate(args.ecm, args.mb, args.ptmin, args.ptmax,
                                        args.power, args.repeats, args.seed, pdf, alpha)
    print(f"\nTOTAL = {total/1000:.6f} +/- {error/1000:.6f} nb")
    print(f"      = {total:.3f} +/- {error:.3f} pb")
    for i, name in enumerate(FLAVOUR_NAMES):
        print(f"  {name} {name}bar: {mean[i]/1000:.6f} +/- {err[i]/1000:.6f} nb")
    print(f"Ratio to reference {args.reference_nb:g} nb: {total/1000/args.reference_nb:.6f}")
    print(f"alpha_s(Q^2=1178 GeV^2) = {float(alpha(1178.0)):.8f}")
    if args.repeats == 1:
        print("Single repeat: no integration error estimate; use --repeats 8 for one.")
    print("Errors are integration errors, not QCD scale/PDF uncertainties.")
    if pdf.frozen:
        print(f"PDF evaluations frozen at table boundaries: {pdf.frozen}")


if __name__ == "__main__":
    main()
